def solve(s, t):
    # Initialize the number of operations to 0
    operations = []

    # Count the number of 'a' and 'b' in both strings
    count_s_a = s.count('a')
    count_s_b = len(s) - count_s_a
    count_t_a = t.count('a')
    count_t_b = len(t) - count_t_a

    # If the number of 'a' in s is less than the number of 'a' in t, we need to swap to make s all 'a'
    if count_s_a < count_t_a:
        for i in range(len(s)):
            if s[i] == 'b':
                # Find the first 'b' in s and swap it with the corresponding 'a' in t
                for j in range(len(t)):
                    if t[j] == 'a':
                        operations.append((i + 1, j + 1))
                        s = s[:i] + 'a' + s[i+1:]
                        t = t[:j] + 'b' + t[j+1:]
